sql_calls.sql:
SELECT sku, gtin, name, pack, flow, price_inr, cost_inr
FROM store.products
ORDER BY name;

SELECT sku, MIN(use_by) AS min_use_by, MAX(use_by) AS max_use_by, COUNT(*) AS rows
FROM store.fresh_deliveries
GROUP BY sku;

SELECT MIN(unit_price) AS min_price, MAX(unit_price) AS max_price, COUNT(DISTINCT unit_price) AS distinct_prices, COUNT(*) AS lines
FROM store.pos_lines
WHERE sku_scanned = 'MILK-TONED-500ML';

SELECT sku, COUNT(*) AS n, MIN(date) AS min_d, MAX(date) AS max_d, MIN(method) AS method
FROM store.forecasts
GROUP BY sku;

SELECT sku, name, pack, flow, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT DISTINCT sku FROM store.daily_sales
EXCEPT
SELECT sku FROM store.products;

SELECT count_ts, sku, book_before, counted, adjustment, "trigger"
FROM store.stock_counts
ORDER BY count_ts;

SELECT sku, gtin, name, pack, flow, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT sum(qty) AS june_units, count(*) AS june_lines
FROM store.pos_lines
WHERE gtin_scanned='2900001001014' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT status, count(*) FROM payments.psp_upi_report
WHERE initiated_ts >= '2026-06-01' AND initiated_ts < '2026-07-01'
GROUP BY status ORDER BY status;

SELECT note, count(*) FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01' AND note IS NOT NULL
GROUP BY note ORDER BY count(*) DESC LIMIT 20;

SELECT attempt, till_status, count(*) FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01'
GROUP BY attempt, till_status ORDER BY attempt, till_status;

SELECT tender, till_status, count(*) FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01'
GROUP BY tender, till_status ORDER BY tender, till_status;

SELECT count(*) AS shipments_june, count(DISTINCT vehicle) AS vehicles
FROM warehouse.shipments
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';
